import{_ as t,o as d,c as a,a3 as o}from"./chunks/framework.DeRSg1wr.js";const g=JSON.parse('{"title":"MDC模式的说明","description":"用 MDC 控制标签位置，区分完整 tl 标签、独立字段与 mdc-enable 开关。","frontmatter":{"title":"MDC模式的说明","date":"2022-09-12T13:48:33.000Z","permalink":"/pages/ddebe2/","description":"用 MDC 控制标签位置，区分完整 tl 标签、独立字段与 mdc-enable 开关。"},"headers":[],"relativePath":"pages/ddebe2/index.md","filePath":"10.文档/090.标签位置的自定义(MDC)/010.MDC模式的说明.md"}'),r={name:"pages/ddebe2/index.md"};function c(p,e,s,n,l,i){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="mdc模式的说明" tabindex="-1">MDC模式的说明 <a class="header-anchor" href="#mdc模式的说明" aria-label="Permalink to &quot;MDC模式的说明&quot;">​</a></h1><p>MDC 允许把标签放在日志行的指定位置，例如放在级别后、消息前：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%d{HH:mm:ss.SSS} %-5level %X{tl} %msg%n</span></span></code></pre></div><p>TLog 入口写入以下字段：</p><table tabindex="0"><thead><tr><th>MDC key</th><th>内容</th></tr></thead><tbody><tr><td><code>tl</code></td><td>按 <code>tlog.pattern</code> 生成的完整标签，方法级业务标签也会临时追加在此</td></tr><tr><td><code>tlogTraceId</code></td><td>当前 traceId</td></tr><tr><td><code>tlogSpanId</code></td><td>当前 spanId</td></tr><tr><td><code>currIp</code></td><td>当前节点 IP</td></tr><tr><td><code>preIp</code></td><td>上游 IP</td></tr><tr><td><code>preIvkHost</code></td><td>上游主机名</td></tr><tr><td><code>preIvkApp</code></td><td>上游应用名</td></tr></tbody></table><h2 id="与消息前缀适配器配合" tabindex="-1">与消息前缀适配器配合 <a class="header-anchor" href="#与消息前缀适配器配合" aria-label="Permalink to &quot;与消息前缀适配器配合&quot;">​</a></h2><p>使用普通 encoder/layout 的 <code>%X{tl}</code> 即可读取入口写入的标签。可以设置 <code>tlog.mdc-enable=true</code>，让保留的 TLog 消息适配器不再重复追加标签。</p><p><code>mdc-enable</code> 不是“是否写入 MDC”的开关；设置为 false 不会关闭或清空这些字段。只有已经建立上下文的日志才有值。</p><p>配置示例：<a href="/pages/eea781/">logback</a>、<a href="/pages/1cc569/">Log4j2</a>、<a href="/pages/1847d5/">旧 Log4j</a>。2.0 已删除 agent/字节码接入，因此不再存在按三种入口划分的 MDC 功能差异。</p><h2 id="业务异步与异步日志" tabindex="-1">业务异步与异步日志 <a class="header-anchor" href="#业务异步与异步日志" aria-label="Permalink to &quot;业务异步与异步日志&quot;">​</a></h2><p>MDC 通常属于当前业务线程。业务任务换线程时，使用 Spring 自动装饰或 <code>TLogExecutors.wrap</code> 同时传播 TLog 和 MDC；日志事件进入异步队列时，则由 appender 保留事件快照。详细说明见<a href="/pages/348797/">MDC 异步</a>。</p>',11)])])}const _=t(r,[["render",c]]);export{g as __pageData,_ as default};
